import * as fs from 'fs';
import * as path from 'path';

// MCP Server Configuration Interface
interface McpServerConfig {
  command: string;
  args: string[];
  status?: string;
}

interface McpConfig {
  mcpServers: Record<string, McpServerConfig>;
}

// Simulated MCP State
interface McpState {
  servers: Map<string, McpServerConfig>;
  tools: Map<string, string[]>;
  initialized: boolean;
}

// Simulated Persistent Store (using JSON file instead of IndexedDB for Node.js)
class PersistentStore {
  private filePath: string;
  private data: any;
  private hydrated: boolean = false;

  constructor(name: string, basePath: string = '.') {
    this.filePath = path.join(basePath, `.persist_${name}.json`);
    this.load();
  }

  private load(): void {
    try {
      if (fs.existsSync(this.filePath)) {
        const content = fs.readFileSync(this.filePath, 'utf-8');
        this.data = JSON.parse(content);
        this.hydrated = true;
        console.log(`[Persistence] State hydrated from ${this.filePath}`);
      } else {
        this.data = {};
        this.hydrated = false;
        console.log(`[Persistence] No existing state, starting fresh`);
      }
    } catch (err) {
      console.error(`[Persistence] Error loading state:`, err);
      this.data = {};
    }
  }

  save(): void {
    try {
      fs.writeFileSync(this.filePath, JSON.stringify(this.data, null, 2));
      console.log(`[Persistence] State saved to ${this.filePath}`);
    } catch (err) {
      console.error(`[Persistence] Error saving state:`, err);
    }
  }

  get<T>(key: string): T | undefined {
    return this.data[key];
  }

  set<T>(key: string, value: T): void {
    this.data[key] = value;
  }

  isHydrated(): boolean {
    return this.hydrated;
  }
}

// MCP System Implementation
class McpSystem {
  private state: McpState;
  private config: McpConfig | null = null;

  constructor() {
    this.state = {
      servers: new Map(),
      tools: new Map(),
      initialized: false
    };
  }

  // Load configuration from file
  loadConfig(configPath: string): void {
    const content = fs.readFileSync(configPath, 'utf-8');
    this.config = JSON.parse(content);
    console.log('[MCP] Configuration loaded from', configPath);
  }

  // Initialize all configured servers
  async initialize(): Promise<void> {
    if (!this.config) {
      throw new Error('No configuration loaded. Call loadConfig first.');
    }

    console.log('[MCP] Initializing system...');

    for (const [serverId, config] of Object.entries(this.config.mcpServers)) {
      await this.addServer(serverId, config);
    }

    this.state.initialized = true;
    console.log('[MCP] System initialized successfully');
  }

  // Add an MCP server
  async addServer(serverId: string, config: McpServerConfig): Promise<void> {
    this.state.servers.set(serverId, config);

    // Register tools based on server type
    if (serverId === 'filesystem') {
      this.state.tools.set(serverId, [
        'read_file',
        'write_file', 
        'list_directory',
        'search_files',
        'get_file_info'
      ]);
      console.log(`[MCP] Server '${serverId}' registered with ${this.state.tools.get(serverId)?.length} tools`);
    }
  }

  // Get all available tools
  getAllTools(): Map<string, string[]> {
    return new Map(this.state.tools);
  }

  // Get server IDs
  getServerIds(): string[] {
    return Array.from(this.state.servers.keys());
  }

  // Count total tools
  getTotalToolCount(): number {
    let count = 0;
    for (const tools of this.state.tools.values()) {
      count += tools.length;
    }
    return count;
  }

  isInitialized(): boolean {
    return this.state.initialized;
  }
}

// Main Demo
async function main(): Promise<void> {
  console.log('='.repeat(60));
  console.log('OpenClaw Claude Code Skill - MCP Demo');
  console.log('='.repeat(60));
  console.log();

  const mcpConfigPath = './mcp_config.json';
  const outputPath = './output/mcp_summary.txt';

  // Create MCP system
  const mcpSystem = new McpSystem();

  // === BEFORE INITIALIZATION ===
  console.log('--- BEFORE INITIALIZATION ---');
  const toolsBefore = mcpSystem.getAllTools();
  const serverIdsBefore = mcpSystem.getServerIds();
  const toolCountBefore = mcpSystem.getTotalToolCount();
  console.log(`Active servers: ${serverIdsBefore.join(', ') || 'none'}`);
  console.log(`Total tools: ${toolCountBefore}`);
  console.log();

  // Load and initialize MCP system
  console.log('--- LOADING CONFIGURATION ---');
  mcpSystem.loadConfig(mcpConfigPath);

  console.log('--- INITIALIZING MCP SYSTEM ---');
  await mcpSystem.initialize();
  console.log();

  // === AFTER INITIALIZATION ===
  console.log('--- AFTER INITIALIZATION ---');
  const toolsAfter = mcpSystem.getAllTools();
  const serverIdsAfter = mcpSystem.getServerIds();
  const toolCountAfter = mcpSystem.getTotalToolCount();
  console.log(`Active servers: ${serverIdsAfter.join(', ')}`);
  console.log(`Total tools: ${toolCountAfter}`);

  console.log('\nAvailable tools by server:');
  for (const [serverId, tools] of toolsAfter.entries()) {
    console.log(`  ${serverId}: [${tools.join(', ')}]`);
  }
  console.log();

  // === STATE PERSISTENCE DEMO ===
  console.log('--- STATE PERSISTENCE DEMO ---');
  const store = new PersistentStore('demo-store');

  console.log(`Hydration status: ${store.isHydrated() ? 'YES (state restored)' : 'NO (fresh start)'}`);

  // Write counter value
  const currentCount = store.get<number>('counter') || 0;
  const newCount = currentCount + 1;
  store.set('counter', newCount);
  console.log(`Counter set to: ${newCount}`);

  // Write item to persistent store
  const items = store.get<string[]>('items') || [];
  const newItem = `demo-item-${Date.now()}`;
  store.set('items', [...items, newItem]);
  console.log(`Item added: ${newItem}`);

  // Persist the state
  store.save();
  console.log();

  // === WRITE OUTPUT SUMMARY ===
  console.log('--- WRITING OUTPUT SUMMARY ---');
  const summary = `
MCP Demo Summary
================
Generated: ${new Date().toISOString()}

Active Server IDs:
${serverIdsAfter.map(id => `  - ${id}`).join('\n')}

Tool Count: ${toolCountAfter}

Tools by Server:
${Array.from(toolsAfter.entries()).map(([id, tools]) => 
  `  ${id}: ${tools.length} tools ([${tools.join(', ')}])`
).join('\n')}

Persistence Demo:
  - Counter value: ${newCount}
  - Items stored: ${items.length}
  - Last item: ${newItem}

Hydration Status: ${store.isHydrated() ? 'State was restored from previous run' : 'Fresh start (no previous state)'}
`;

  fs.writeFileSync(outputPath, summary.trim());
  console.log(`Summary written to: ${outputPath}`);
  console.log();
  console.log('='.repeat(60));
  console.log('Demo completed successfully!');
  console.log('='.repeat(60));
}

main().catch(console.error);
EOF\n",
      "duration": 0.5
    }
  ],
